from pathlib import Path
import base64

ROOT = Path("src/main/resources/assets/rustarmor")

# 64x64 Minecraft armor UV texture: Rust-style metal face mask and chestplate.
ARMOR = ""
# Inventory icons are original pixel-art interpretations of Rust's metal armor.
FACEMASK = ""
CHESTPLATE = ""

def write(relative_path, encoded):
    target = ROOT / relative_path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(base64.b64decode(encoded))

write("textures/entity/equipment/humanoid/rust_metal.png", ARMOR)
write("textures/item/rust_metal_facemask.png", FACEMASK)
write("textures/item/rust_metal_chestplate.png", CHESTPLATE)
print("Generated Rust-style armor layer and inventory icons.")
